function parseRetryAfterMsWorker(value) {
  if (!value) return undefined;
  const secs = parseInt(value, 10);
  if (!isFinite(secs) || String(secs) !== String(value).trim()) return undefined;
  return Math.min(secs * 1000, 30000);
}

